/* نلون المربع الناقص بالمخزن + شريط فوك بيه أسماء الناقص */
function lowMark(left){
  const off=settings.low.on===false, low=[];
  LOW_ITEMS.forEach(([k,name,id])=>{
    const e=document.getElementById(id), c=e&&e.closest('.card'); if(!c) return;
    const m=+settings.low.min[k]||0, bad=!off&&left[k]!==null&&m&&left[k]<m;
    if(bad) low.push({k,name,id,v:left[k]});
    const h=c.querySelector(':scope > h3');
    let t=h&&h.querySelector('.low-tag');
    const mine=c.dataset.lowk?c.dataset.lowk.split(','):[];
    const others=mine.filter(x=>x!==k), now=bad?others.concat(k):others;
    c.dataset.lowk=now.join(',');
    c.classList.toggle('low-card',now.length>0);
    if(h){
      if(!t){ t=document.createElement('span'); t.className='low-tag'; h.insertBefore(t,h.querySelector('.colbtn')) }
      const its=now.map(x=>LOW_ITEMS.find(i=>i[0]===x)).filter(Boolean);
      t.textContent=its.length?('ناقص · باقي '+its.map(i=>fmt(left[i[0]])).join(' / ')):''; t.hidden=!its.length;
    }
  });
  const bn=document.getElementById('lowBanner'); if(!bn) return;
  bn.hidden=!low.length;
  bn.innerHTML=low.length?('<b>ناقص:</b> '+low.map(x=>`<button type="button" data-id="${x.id}">${esc(x.name)} (${fmt(x.v)})</button>`).join('')):'';
}
document.getElementById('lowBanner').addEventListener('click',e=>{
  const b=e.target.closest('button[data-id]'); if(!b) return;
  const c=document.getElementById(b.dataset.id).closest('.card'); if(!c) return;
  if(c.classList.contains('collapsed')){ const t=c.querySelector('.colbtn'); if(t) t.click() }
  c.scrollIntoView({behavior:'smooth',block:'center'});
  c.classList.remove('low-flash'); void c.offsetWidth; c.classList.add('low-flash');
});
  lowMark(left);
