  <div class="low-banner" id="lowBanner" hidden></div>
.low-banner{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:0 0 12px;padding:10px 14px;border:1px solid #F5A623;border-radius:12px;background:rgba(245,166,35,.08)}
.low-banner[hidden]{display:none}
.low-banner b{color:#F5A623}
.low-banner button{min-height:36px;padding:0 12px;border-radius:999px;border:1px solid #F5A623;background:transparent;color:#F5A623;font:inherit;font-size:14px;cursor:pointer}
.card.low-card{border-color:#F5A623 !important;box-shadow:0 0 0 1px #F5A623 inset}
.low-tag{font-size:12.5px;font-weight:700;color:#111;background:#F5A623;border-radius:999px;padding:2px 10px;margin-inline-start:auto}
.low-tag[hidden]{display:none}
.card.low-flash{animation:lowfl 1.2s 2}
@keyframes lowfl{50%{box-shadow:0 0 0 4px #F5A623}}
@media(prefers-reduced-motion:reduce){.card.low-flash{animation:none}}
